DROP TABLE IF EXISTS `articles`;
CREATE TABLE "articles" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "content_html" text, "thumbnail_id" integer, "thumbnail_alt" varchar, "category_id" integer, "author_id" integer, "author_display_name" varchar, "meta_title" varchar, "meta_description" text, "is_featured" tinyint(1) not null default '0', "status" varchar not null default 'draft', "published_at" datetime, "lock_version" integer not null default '1', "created_by" integer, "updated_by" integer, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("thumbnail_id") references "media_assets"("id") on delete set null, foreign key("category_id") references "article_categories"("id") on delete set null, foreign key("author_id") references "users"("id") on delete set null, foreign key("created_by") references "users"("id") on delete set null, foreign key("updated_by") references "users"("id") on delete set null);

-- Data for `articles` (7 rows)
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, 'How to Select Between MCCB and ACB for Industrial Main Switchboards (IEC 60947 Standards)', 'how-to-select-mccb-vs-acb-for-industrial-panels', 'A comprehensive engineering guide on short-circuit breaking capacities (Icu vs Ics), electronic trip units, selective coordination, and cost optimization when sizing low-voltage main switchboards.', '<h2>Understanding the Fundamental Differences Between ACB and MCCB</h2>
<p>In modern industrial facilities, selecting between an Air Circuit Breaker (ACB) and a Moulded Case Circuit Breaker (MCCB) is a pivotal engineering decision that impacts both upfront capital expenditure and long-term facility reliability. Under IEC 60947-2 standards, both devices provide overload and short-circuit protection, but their internal architecture, breaking dynamics, and maintainability differ fundamentally.</p>

<h3>1. Current Ratings & Frame Capacities</h3>
<p>ACBs, such as the <strong>Schneider Electric MasterPact MTZ</strong> and <strong>NW series</strong>, are primarily deployed at the incomer of Low Voltage Main Distribution Panels (LVMDP) with nominal currents ranging from <strong>630A up to 6300A</strong>. MCCBs, like the ComPacT NSX, are optimal for sub-distribution feeders ranging from <strong>16A up to 1600A</strong>.</p>

<h3>2. Rated Service Short-Circuit Capacity (Ics) vs Ultimate Capacity (Icu)</h3>
<p>For critical manufacturing plants and data centers, specifying <code>Ics = 100% Icu</code> is essential. High-end ACBs deliver Ics ratings of 50kA, 65kA, or 100kA at 415V, ensuring the breaker can interrupt a maximum fault current repeatedly without requiring component replacement.</p>

<h3>3. Digital Electronic Trip Units (Micrologic)</h3>
<p>Modern ACBs feature advanced microprocessor trip units (such as Micrologic 2.0X to 7.0X) that incorporate built-in Class 1 energy metering, harmonic analysis up to the 31st order, and Bluetooth/Ethernet telemetries for predictive asset health monitoring.</p>', NULL, NULL, 2, 1, 'PT. ATS Engineering Editorial', 'How to Select Between MCCB and ACB for Industrial Main Switchboards (IEC 60947 Standards) | PT. Anugerah Tama Sejati', 'A comprehensive engineering guide on short-circuit breaking capacities (Icu vs Ics), electronic trip units, selective coordination, and cost optimization when sizing low-voltage main switchboards.', 1, 'published', '2026-09-08 04:08:31', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 04:08:31', NULL);
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2, 'Power Factor Correction: Designing 600kVAR Automatic Capacitor Banks for Manufacturing Plants', 'designing-600kvar-automatic-capacitor-banks-power-factor', 'Eliminating PLN kVARh surcharge penalties, sizing detuned anti-resonance reactors (7% and 14%), and selecting heavy-duty capacitor steps for inductive motor loads.', '<h2>Why Industrial Facilities Face High kVARh Penalties</h2>
<p>In heavy industrial operations involving AC induction motors, welding machines, and transformers, inductive reactive power lowers the overall power factor (cos φ) below PLN’s threshold of <strong>0.85</strong>. Maintaining a power factor between <strong>0.95 and 0.98</strong> not only prevents financial penalties but also increases transformer capacity and reduces I²R cable losses.</p>

<h3>Detuned Reactor Sizing: 7% vs 14%</h3>
<p>When nonlinear loads (VFDs, UPS, LED drivers) constitute more than 20% of the total load, connecting standard capacitors creates dangerous parallel harmonic resonance. Introducing <strong>7% detuned reactors</strong> tunes the bank to 189 Hz (below the dominant 5th harmonic of 250 Hz), protecting capacitors from catastrophic overvoltage and current distortion.</p>', NULL, NULL, 3, 1, 'PT. ATS Engineering Editorial', 'Power Factor Correction: Designing 600kVAR Automatic Capacitor Banks for Manufacturing Plants | PT. Anugerah Tama Sejati', 'Eliminating PLN kVARh surcharge penalties, sizing detuned anti-resonance reactors (7% and 14%), and selecting heavy-duty capacitor steps for inductive motor loads.', 1, 'published', '2026-09-05 04:08:31', 1, 1, 1, '2026-09-10 04:08:31', '2026-09-10 04:08:31', NULL);
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3, 'Variable Frequency Drive (VFD) Harmonics Mitigation in Industrial Pumping Systems', 'vfd-harmonics-mitigation-industrial-pumping-systems', 'Mitigating THD-i and THD-v distortion caused by 6-pulse diode rectifiers, incorporating DC chokes and passive harmonic filters to protect industrial motors and instrumentation.', '<h2>Addressing Electrical Pollution from 6-Pulse Inverters</h2>
<p>Variable Frequency Drives (VFDs) provide substantial energy savings for centrifugal pumps and blowers. However, conventional 6-pulse rectifier front-ends generate significant 5th, 7th, 11th, and 13th harmonic currents, resulting in total harmonic current distortion (THD-i) frequently exceeding 35%.</p>

<h3>Mitigation Strategies</h3>
<p>Utilizing <strong>Schneider Electric Altivar Process ATV930</strong> drives equipped with built-in DC bus chokes reduces THD-i to below 48%. For stringent IEEE 519 compliance (THD-i < 5% at Point of Common Coupling), passive harmonic filters or Active Front End (AFE) regenerative converters should be engineered into the Motor Control Center (MCC).</p>', NULL, NULL, 4, 1, 'PT. ATS Engineering Editorial', 'Variable Frequency Drive (VFD) Harmonics Mitigation in Industrial Pumping Systems | PT. Anugerah Tama Sejati', 'Mitigating THD-i and THD-v distortion caused by 6-pulse diode rectifiers, incorporating DC chokes and passive harmonic filters to protect industrial motors and instrumentation.', 1, 'published', '2026-09-02 04:08:31', 1, 1, 1, '2026-09-10 04:08:31', '2026-09-10 04:08:31', NULL);
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (4, 'Motor Control Center (MCC) Sizing: Type-2 Coordination & Arc Flash Safety in Heavy Industry', 'mcc-sizing-type-2-coordination-arc-flash-safety', 'Understanding IEC 60947-4-1 Type-2 coordination between circuit breakers, contactors, and thermal relays to ensure zero contact welding and maximum personnel protection during short circuits.', '<h2>The Criticality of Type-2 Coordination</h2>
<p>In continuous manufacturing environments like chemical, cement, and food processing plants, an electrical fault in a single motor starter feeder must not incapacitate the entire switchboard. Under IEC 60947-4-1, <strong>Type-2 Coordination</strong> mandates that after a short-circuit fault, the contactor and overload relay must remain operational and suffer no contact welding or insulation degradation.</p>

<h3>Component Synergy</h3>
<p>Achieving certified Type-2 coordination requires tested combinations of <strong>TeSys Deca / TeSys Giga contactors</strong> paired with precisely calibrated <strong>ComPacT NSX thermal-magnetic or electronic circuit breakers</strong>.</p>', NULL, NULL, 5, 1, 'PT. ATS Engineering Editorial', 'Motor Control Center (MCC) Sizing: Type-2 Coordination & Arc Flash Safety in Heavy Industry | PT. Anugerah Tama Sejati', 'Understanding IEC 60947-4-1 Type-2 coordination between circuit breakers, contactors, and thermal relays to ensure zero contact welding and maximum personnel protection during short circuits.', '0', 'published', '2026-08-29 04:08:31', 1, 1, 1, '2026-09-10 04:08:31', '2026-09-10 04:08:31', NULL);
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (5, 'Smart Electrical Switchboards: Integrating Modbus RS-485 & IoT Energy Gateways into LVMDP', 'smart-electrical-switchboards-modbus-iot-energy-gateways', 'Transforming conventional power distribution panels into connected Industry 4.0 digital assets with real-time branch energy monitoring, thermal busbar sensors, and cloud SCADA telemetry.', '<h2>Digitalizing Industrial Power Infrastructure</h2>
<p>The convergence of operational technology (OT) and digital IoT allows electrical engineers to transition from reactive firefighting to predictive condition-based maintenance. Equipping LVMDP switchgear with digital power meters and wireless thermal sensors enables continuous asset tracking.</p>

<h3>Communication Architecture</h3>
<p>Daisy-chained <strong>Modbus RS-485 serial loops</strong> aggregate real-time electrical data from feeder meters into edge gateways like the <strong>Schneider EcoStruxure Panel Server</strong>, transmitting encrypted telemetry to plant supervisory SCADA or cloud dashboards via Ethernet/Wi-Fi.</p>', NULL, NULL, 6, 1, 'PT. ATS Engineering Editorial', 'Smart Electrical Switchboards: Integrating Modbus RS-485 & IoT Energy Gateways into LVMDP | PT. Anugerah Tama Sejati', 'Transforming conventional power distribution panels into connected Industry 4.0 digital assets with real-time branch energy monitoring, thermal busbar sensors, and cloud SCADA telemetry.', '0', 'published', '2026-08-25 04:08:31', 1, 1, 1, '2026-09-10 04:08:31', '2026-09-10 04:08:31', NULL);
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (6, 'Automatic Transfer Switch (ATS) & Generator Synchronizing: Ensuring Zero Downtime for Tier-3 Facilities', 'ats-generator-synchronizing-zero-downtime-tier-3', 'Engineering closed-transition transfer mechanisms, Socomec ATyS motorized switches, and automatic mains failure (AMF) logic to protect critical IT and hospital backup power grids.', '<h2>Uncompromising Power Reliability for Critical Loads</h2>
<p>When the main utility grid experiences an outage or voltage sag, automatic transfer systems must detect the anomaly and command diesel generators to start, synchronize, and take over critical plant feeders in under 10 seconds.</p>

<h3>Open vs Closed Transition Switching</h3>
<p>Standard open-transition (break-before-make) switches induce a brief momentary disruption during transfer. For sensitive electronics, <strong>closed-transition (make-before-break) systems</strong> achieve seamless bumpless paralleling for 100 milliseconds, ensuring zero interruption to mission-critical infrastructure.</p>', NULL, NULL, 7, 1, 'PT. ATS Engineering Editorial', 'Automatic Transfer Switch (ATS) & Generator Synchronizing: Ensuring Zero Downtime for Tier-3 Facilities | PT. Anugerah Tama Sejati', 'Engineering closed-transition transfer mechanisms, Socomec ATyS motorized switches, and automatic mains failure (AMF) logic to protect critical IT and hospital backup power grids.', '0', 'published', '2026-08-20 04:08:31', 1, 1, 1, '2026-09-10 04:08:32', '2026-09-10 04:08:32', NULL);
INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `content_html`, `thumbnail_id`, `thumbnail_alt`, `category_id`, `author_id`, `author_display_name`, `meta_title`, `meta_description`, `is_featured`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (7, 'Industrial Cable Sizing, Derating Factors & Voltage Drop Calculations for 3-Phase Feeders', 'industrial-cable-sizing-derating-voltage-drop-calculations', 'A practical methodology for sizing copper and aluminum XLPE power cables (Jembo, Supreme) in cable trays, incorporating ambient temperature and grouping derating under PUIL 2011.', '<h2>Ensuring Voltage Compliance Across Long Factory Runs</h2>
<p>Undersized electrical cables generate excessive resistive heating (I²R loss), lead to premature insulation failure, and cause voltage drops exceeding the statutory <strong>5% limit</strong> under Indonesian General Electrical Installation Regulations (PUIL 2011 / SPLN).</p>

<h3>Step-by-Step Sizing Criteria</h3>
<ol>
  <li><strong>Full Load Current (Ib):</strong> Calculate three-phase running current: <code>Ib = P / (√3 × V × cos φ × η)</code>.</li>
  <li><strong>Environmental Derating:</strong> Multiply nominal cable ampacity by ambient temperature factor (k1) and grouping proximity factor (k2) in perforated cable trays.</li>
  <li><strong>Voltage Drop Check:</strong> Ensure: <code>ΔV = (√3 × I × L × (R cos φ + X sin φ)) / 1000 ≤ 5% of 400V (20V)</code>.</li>
</ol>', NULL, NULL, 8, 1, 'PT. ATS Engineering Editorial', 'Industrial Cable Sizing, Derating Factors & Voltage Drop Calculations for 3-Phase Feeders | PT. Anugerah Tama Sejati', 'A practical methodology for sizing copper and aluminum XLPE power cables (Jembo, Supreme) in cable trays, incorporating ambient temperature and grouping derating under PUIL 2011.', '0', 'published', '2026-08-13 04:08:31', 1, 1, 1, '2026-09-10 04:08:32', '2026-09-10 04:08:32', NULL);

