-- --------------------------------------------------------
-- Table structure for `pages`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `pages`;
CREATE TABLE "pages" ("id" integer primary key autoincrement not null, "page_key" varchar not null, "title" varchar not null, "slug" varchar not null, "content_html" text, "sections_data" text, "meta_title" varchar, "meta_description" text, "status" varchar not null default 'published', "published_at" datetime, "lock_version" integer not null default '1', "created_by" integer, "updated_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("created_by") references "users"("id") on delete set null, foreign key("updated_by") references "users"("id") on delete set null);

-- Data for `pages` (1 rows)
INSERT INTO `pages` (`id`, `page_key`, `title`, `slug`, `content_html`, `sections_data`, `meta_title`, `meta_description`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (1, 'about-us', 'About PT. Anugerah Tama Sejati', 'about-us', '<h2>Your Trusted Electrical Engineering Partner</h2><p>PT. Anugerah Tama Sejati (ATS) is an established premier electrical component distributor headquartered in Surabaya, East Java. Serving industrial EPCs, panel builders, contractors, and original equipment manufacturers across Indonesia, we provide genuine, certified electrical distribution and industrial automation components.</p><h3>Authorized Official Distributor</h3><p>As an authorized partner for global leaders including Schneider Electric, GAE, Legrand, and Socomec, we guarantee 100% genuine products with manufacturer warranties, origin documentation, and expert engineering consultation.</p>', '{"vision":"To become Indonesia''s most dependable, technologically advanced, and customer-centric electrical engineering supplier.","mission":"Delivering authentic electrical components promptly, offering certified engineering sizing guidance, and fostering long-term industrial partnerships with integrity.","established_year":"2010"}', 'About Us - PT. Anugerah Tama Sejati', 'Learn about PT. Anugerah Tama Sejati, premier authorized electrical and automation distributor in Surabaya, Indonesia.', 'published', '2026-09-10 01:35:13', 1, 1, 1, '2026-09-10 01:35:13', '2026-09-10 01:35:13');

