-- --------------------------------------------------------
-- Table structure for `price_lists`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `price_lists`;
CREATE TABLE "price_lists" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "brand_name" varchar not null, "edition_year" varchar, "category" varchar, "description" text, "thumbnail_url" varchar, "view_url" varchar not null, "download_url" varchar, "file_size" varchar not null default 'PDF Document', "tax_note" varchar, "is_featured" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);

-- Data for `price_lists` (7 rows)
INSERT INTO `price_lists` (`id`, `title`, `slug`, `brand_name`, `edition_year`, `category`, `description`, `thumbnail_url`, `view_url`, `download_url`, `file_size`, `tax_note`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (1, 'Vinsa Pricelist - 2026', 'vinsa-pricelist-2026', 'Vinsa', 2026, 'Box Panel & Enclosures', 'Daftar harga resmi produk Vinsa terbaru tahun 2026. Termasuk PPN 11%. Meliputi Box Panel Wall Mounting & Free Standing, Cable Lug, Contactor, dan Terminal Block.', 'images/pricelists/17.jpg', 'https://drive.google.com/file/d/1cR0FGRAqQXo8O2gOqGxHNkfLrWmgGkdU/view?usp=sharing', 'https://drive.google.com/uc?export=download&id=1cR0FGRAqQXo8O2gOqGxHNkfLrWmgGkdU', 'PDF Document • 2026 Edition', 'Termasuk PPN 11%', 1, 1, 1, '2026-09-10 06:42:27', '2026-09-10 06:42:27');
INSERT INTO `price_lists` (`id`, `title`, `slug`, `brand_name`, `edition_year`, `category`, `description`, `thumbnail_url`, `view_url`, `download_url`, `file_size`, `tax_note`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (2, 'Schneider Pricelist General - 2025', 'schneider-pricelist-general-2025', 'Schneider Electric', 2025, 'Power Distribution & Industrial Automation', 'Schneider Price List General. Harga katalog resmi belum termasuk PPN 11% (Tanpa Pembulatan). Meliputi Air Circuit Breaker (ACB) MasterPact MTZ/NT/NW, MCCB Compact NSX, Inverter Altivar, dan TeSys Contactor.', 'images/pricelists/16.jpg', 'https://drive.google.com/file/d/1BJLQbLzGy4Nr08vOcO5rjkqp9IRk_R9J/view?usp=drive_link', 'https://drive.google.com/uc?export=download&id=1BJLQbLzGy4Nr08vOcO5rjkqp9IRk_R9J', 'PDF Document • 2025 Edition', 'Belum Termasuk PPN 11%', 1, 1, 2, '2026-09-10 06:42:27', '2026-09-10 06:42:27');
INSERT INTO `price_lists` (`id`, `title`, `slug`, `brand_name`, `edition_year`, `category`, `description`, `thumbnail_url`, `view_url`, `download_url`, `file_size`, `tax_note`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (3, 'Schneider Pricelist Retail - 2025', 'schneider-pricelist-retail-2025', 'Schneider Electric', 2025, 'Residential & Commercial Wiring Devices', 'Schneider Price List Retail. Harga katalog resmi belum termasuk PPN 11% (Tanpa Pembulatan). Meliputi Mini Circuit Breaker (MCB) Domae, IK60N, RCBO Slim, Sakelar & Stop Kontak AvatarOn, S-Classic, dan Weatherproof Sockets.', 'images/pricelists/15.jpg', 'https://drive.google.com/file/d/10L-6vKKbkE5JA0xW2rcGXztzMfkHMMGd/view?usp=drive_link', 'https://drive.google.com/uc?export=download&id=10L-6vKKbkE5JA0xW2rcGXztzMfkHMMGd', 'PDF Document • 2025 Edition', 'Belum Termasuk PPN 11%', 1, 1, 3, '2026-09-10 06:42:27', '2026-09-10 06:42:27');
INSERT INTO `price_lists` (`id`, `title`, `slug`, `brand_name`, `edition_year`, `category`, `description`, `thumbnail_url`, `view_url`, `download_url`, `file_size`, `tax_note`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (4, 'GAE Pricelist - 2023', 'gae-pricelist-2023', 'GAE', 2023, 'Power Quality & Capacitor Bank', 'Price List GAE resmi. Harga yang tercantum pada katalog belum termasuk PPN 11% (tanpa pembulatan). Meliputi GAE Power Capacitor Bank, Power Factor Controller, Reaktor Detuned, dan Fuse Switch Disconnector.', 'images/pricelists/14.jpg', 'https://drive.google.com/file/d/1K5HOpAQbzr98N20i024CxPu18TOO7gFM/view?usp=drive_link', 'https://drive.google.com/uc?export=download&id=1K5HOpAQbzr98N20i024CxPu18TOO7gFM', 'PDF Document • 2023 Edition', 'Belum Termasuk PPN 11%', '0', 1, 4, '2026-09-10 06:42:27', '2026-09-10 06:42:27');
INSERT INTO `price_lists` (`id`, `title`, `slug`, `brand_name`, `edition_year`, `category`, `description`, `thumbnail_url`, `view_url`, `download_url`, `file_size`, `tax_note`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (5, 'GAE Price List Metering & Panel Accessories 2025', 'gae-price-list-metering-panel-accessories-2025', 'GAE', 2025, 'Metering & Panel Accessories', 'Price List Metering & Panel Accessories GAE 2025. Harga belum termasuk PPN 11% (tanpa pembulatan). Meliputi Current Transformer (CT), Digital Multi-Function Power Meter, Busbar Support Insulator, dan Aksesoris Perakitan Panel.', 'images/pricelists/13.jpg', 'https://drive.google.com/file/d/1tWA-e6PMXZOKkYkJzhTLoijv6g78vAOK/view?usp=drive_link', 'https://drive.google.com/uc?export=download&id=1tWA-e6PMXZOKkYkJzhTLoijv6g78vAOK', 'PDF Document • 2025 Edition', 'Belum Termasuk PPN 11%', '0', 1, 5, '2026-09-10 06:42:27', '2026-09-10 06:42:27');
