DROP TABLE IF EXISTS `products`;
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "sku" varchar not null, "normalized_sku" varchar not null, "name" varchar not null, "slug" varchar not null, "short_description" varchar, "description_html" text, "brand_id" integer, "primary_category_id" integer, "main_image_id" integer, "datasheet_id" integer, "meta_title" varchar, "meta_description" varchar, "is_featured" tinyint(1) not null default '0', "sort_order" integer not null default '0', "status" varchar not null default 'draft', "published_at" datetime, "lock_version" integer not null default '1', "created_by" integer, "updated_by" integer, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("brand_id") references "brands"("id") on delete set null, foreign key("primary_category_id") references "product_categories"("id") on delete set null, foreign key("main_image_id") references "media_assets"("id") on delete set null, foreign key("datasheet_id") references "media_assets"("id") on delete set null, foreign key("created_by") references "users"("id") on delete set null, foreign key("updated_by") references "users"("id") on delete set null);

-- Data for `products` (6 rows)
INSERT INTO `products` (`id`, `sku`, `normalized_sku`, `name`, `slug`, `short_description`, `description_html`, `brand_id`, `primary_category_id`, `main_image_id`, `datasheet_id`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, 'SE-MTZ1-08H1', 'SE-MTZ1-08H1', 'Schneider MasterPact MTZ1 08 H1 Air Circuit Breaker (ACB)', 'schneider-masterpact-mtz1-08h1-acb', 'Air Circuit Breaker (ACB) 800A 3-Pole 42kA with Micrologic 2.0X trip unit.', '<p>MasterPact MTZ1 embeds advanced class 1 metering and digital connectivity into standard low-voltage main switchboard applications. Designed to optimize uptime and electrical safety.</p>', 1, 1, NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:13', 1, 1, 1, '2026-09-10 01:35:13', '2026-09-10 01:35:13', NULL);
INSERT INTO `products` (`id`, `sku`, `normalized_sku`, `name`, `slug`, `short_description`, `description_html`, `brand_id`, `primary_category_id`, `main_image_id`, `datasheet_id`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2, 'SE-NSX100F-TM80D', 'SE-NSX100F-TM80D', 'Schneider ComPact NSX100F 80A 3P 36kA MCCB', 'schneider-compact-nsx100f-80a-3p-36ka-mccb', 'Molded Case Circuit Breaker (MCCB) 80A 3-Pole 36kA with TM-D thermal-magnetic trip unit.', '<p>ComPact NSX100F is a complete circuit breaker optimized for industrial feeder protection, switchboard sub-distribution, and motor feeders.</p>', 1, 1, NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);
INSERT INTO `products` (`id`, `sku`, `normalized_sku`, `name`, `slug`, `short_description`, `description_html`, `brand_id`, `primary_category_id`, `main_image_id`, `datasheet_id`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3, 'SE-ATV630U55N4', 'SE-ATV630U55N4', 'Schneider Altivar Process ATV630 5.5kW Variable Speed Drive', 'schneider-altivar-process-atv630-5kw-vfd', 'Variable Speed Drive (VFD/Inverter) 5.5kW / 7.5HP 380-480V 3-Phase for pumps and fans.', '<p>Altivar Process ATV630 variable speed drive focuses on fluid management processing and energy efficiency. Built-in Ethernet dual port and embedded web server.</p>', 1, 3, NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);
INSERT INTO `products` (`id`, `sku`, `normalized_sku`, `name`, `slug`, `short_description`, `description_html`, `brand_id`, `primary_category_id`, `main_image_id`, `datasheet_id`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (4, 'SE-LC1D25M7', 'SE-LC1D25M7', 'Schneider TeSys D Contactor LC1D25 25A 220V AC', 'schneider-tesys-d-contactor-lc1d25m7', '3-Pole Magnetic Contactor 25A AC-3 11kW with 220V AC 50/60Hz control coil.', '<p>TeSys D contactor combines high reliability with mechanical robustness, offering 1 NO + 1 NC auxiliary contacts built-in.</p>', 1, 2, NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);
INSERT INTO `products` (`id`, `sku`, `normalized_sku`, `name`, `slug`, `short_description`, `description_html`, `brand_id`, `primary_category_id`, `main_image_id`, `datasheet_id`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (5, 'LEG-001924', 'LEG-001924', 'Legrand Plexo™ Weatherproof Enclosure IP66 12 Modules', 'legrand-plexo-weatherproof-enclosure-ip66-12-modules', 'Surface mounting industrial IP66 weatherproof enclosure box for 12 DIN rail modules.', '<p>Plexo modular industrial enclosure boxes withstand tough weather, dust, and humid atmospheres with self-extinguishing polystyrene construction.</p>', 3, 4, NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);
INSERT INTO `products` (`id`, `sku`, `normalized_sku`, `name`, `slug`, `short_description`, `description_html`, `brand_id`, `primary_category_id`, `main_image_id`, `datasheet_id`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (6, 'GAE-EM-3000', 'GAE-EM-3000', 'GAE Digital Power Meter EM-3000 Multifunction Analyzer', 'gae-digital-power-meter-em3000', 'Class 0.5S digital 3-phase multifunction energy meter with RS485 Modbus RTU.', '<p>GAE EM-3000 delivers true RMS measurement of voltage, current, active power, reactive power, power factor, frequency, and total harmonic distortion (THD).</p>', 2, 5, NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);

