-- --------------------------------------------------------
-- Table structure for `projects`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `projects`;
CREATE TABLE "projects" ("id" integer primary key autoincrement not null, "project_code" varchar not null, "title" varchar not null, "slug" varchar not null, "summary" text, "content_html" text, "category_id" integer, "client_name" varchar, "location" varchar, "completion_year" varchar, "scope_of_work" text, "cover_image_id" integer, "cover_alt" varchar, "meta_title" varchar, "meta_description" text, "is_featured" tinyint(1) not null default '0', "sort_order" integer not null default '0', "status" varchar not null default 'draft', "published_at" datetime, "lock_version" integer not null default '1', "created_by" integer, "updated_by" integer, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("category_id") references "project_categories"("id") on delete set null, foreign key("cover_image_id") references "media_assets"("id") on delete set null, foreign key("created_by") references "users"("id") on delete set null, foreign key("updated_by") references "users"("id") on delete set null);

-- Data for `projects` (10 rows)
INSERT INTO `projects` (`id`, `project_code`, `title`, `slug`, `summary`, `content_html`, `category_id`, `client_name`, `location`, `completion_year`, `scope_of_work`, `cover_image_id`, `cover_alt`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, 'PRJ-SUB-2500A', '2500A Low Voltage Main Distribution Panel (LVMDP) Substation', '2500a-low-voltage-main-distribution-panel-substation', 'Engineering assembly and component supply of dual-incomer 2500A Schneider MasterPact MTZ Air Circuit Breakers.', '<p>Supply and integration of primary distribution switchboard for a heavy industrial plant in East Java. Fitted with Schneider MasterPact MTZ ACB, busbar sizing, and GAE power quality analyzer metering.</p>', 1, NULL, 'Gresik, East Java', 2024, 'Component Supply, Technical BoQ Consultation, Busbar Coordination', NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);
INSERT INTO `projects` (`id`, `project_code`, `title`, `slug`, `summary`, `content_html`, `category_id`, `client_name`, `location`, `completion_year`, `scope_of_work`, `cover_image_id`, `cover_alt`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2, 'PRJ-COLD-01', 'Cold Storage Precision Temperature & Motor Control Center (MCC)', 'cold-storage-precision-temperature-motor-control-center', 'Multi-compressor motor control center utilizing Schneider Altivar ATV630 VFDs and TeSys D contactors.', '<p>Turnkey motor management system for seafood cold storage facility in Surabaya. Ensured seamless inverter speed modulation, energy conservation, and automated backup switching.</p>', 2, NULL, 'Surabaya, East Java', 2025, 'MCC Panel Supply, VFD Inverter Tuning, Harmonics Filtration', NULL, NULL, NULL, NULL, 1, '0', 'published', '2026-09-10 01:35:14', 1, 1, 1, '2026-09-10 01:35:14', '2026-09-10 01:35:14', NULL);
INSERT INTO `projects` (`id`, `project_code`, `title`, `slug`, `summary`, `content_html`, `category_id`, `client_name`, `location`, `completion_year`, `scope_of_work`, `cover_image_id`, `cover_alt`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3, 'PRJ-2024-PKW', 'Pakuwon Mall & Superblock Power Substation', 'pakuwon-mall-superblock-power-substation', 'Complete engineering, fabrication, and supply of Low Voltage Main Distribution Panels (LVMDP) for Surabaya’s largest commercial superblock.', '<p>Complete engineering, fabrication, and supply of Low Voltage Main Distribution Panels (LVMDP) for Surabaya’s largest commercial superblock.</p><p>Equipped with Schneider MasterPact MTZ 3200A • GAE Capacitor 600kVAR to ensure full industrial compliance under SPLN and IEC 61439 standards.</p>', 4, 'Pakuwon Group', 'West Surabaya, Indonesia', 2024, 'Schneider MasterPact MTZ 3200A • GAE Capacitor 600kVAR', NULL, 'Pakuwon Mall Power Substation LVMDP Switchboard', 'Pakuwon Mall & Superblock Power Substation | PT. Anugerah Tama Sejati', 'Complete engineering, fabrication, and supply of Low Voltage Main Distribution Panels (LVMDP) for Surabaya’s largest commercial superblock.', 1, 1, 'published', '2026-07-22 04:08:12', 1, 1, 1, '2026-09-10 04:08:12', '2026-09-10 04:08:12', NULL);
INSERT INTO `projects` (`id`, `project_code`, `title`, `slug`, `summary`, `content_html`, `category_id`, `client_name`, `location`, `completion_year`, `scope_of_work`, `cover_image_id`, `cover_alt`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (4, 'PRJ-2024-IDF', 'Indofood CBP Motor Control Center (MCC)', 'indofood-cbp-motor-control-center-mcc', 'Smart motor control center switchboards equipped with harmonic suppression inverters and thermal predictive monitoring for continuous food processing.', '<p>Smart motor control center switchboards equipped with harmonic suppression inverters and thermal predictive monitoring for continuous food processing.</p><p>Equipped with Schneider Altivar ATV930 VFD • TeSys Deca Contactors to ensure full industrial compliance under SPLN and IEC 61439 standards.</p>', 5, 'PT Indofood CBP Sukses Makmur Tbk', 'Pasuruan, East Java', 2024, 'Schneider Altivar ATV930 VFD • TeSys Deca Contactors', NULL, 'Indofood CBP Smart MCC Switchboard Panels', 'Indofood CBP Motor Control Center (MCC) | PT. Anugerah Tama Sejati', 'Smart motor control center switchboards equipped with harmonic suppression inverters and thermal predictive monitoring for continuous food processing.', 1, 2, 'published', '2026-08-14 04:08:16', 1, 1, 1, '2026-09-10 04:08:16', '2026-09-10 04:08:16', NULL);
INSERT INTO `projects` (`id`, `project_code`, `title`, `slug`, `summary`, `content_html`, `category_id`, `client_name`, `location`, `completion_year`, `scope_of_work`, `cover_image_id`, `cover_alt`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (5, 'PRJ-2024-BMI', 'PT Bumi Menara Internusa Cold Chain & SCADA', 'bumi-menara-internusa-cold-chain-scada', 'Integrated industrial refrigeration power distribution panels with dual-redundant automatic transfer switching and IoT SCADA telemetries.', '<p>Integrated industrial refrigeration power distribution panels with dual-redundant automatic transfer switching and IoT SCADA telemetries.</p><p>Equipped with Socomec ATS 1600A • GAE Digital Power Metering to ensure full industrial compliance under SPLN and IEC 61439 standards.</p>', 6, 'PT Bumi Menara Internusa', 'Dampit & Surabaya', '2023 - 2024', 'Socomec ATS 1600A • GAE Digital Power Metering', NULL, 'Cold Chain Refrigeration Automation Switchboards', 'PT Bumi Menara Internusa Cold Chain & SCADA | PT. Anugerah Tama Sejati', 'Integrated industrial refrigeration power distribution panels with dual-redundant automatic transfer switching and IoT SCADA telemetries.', 1, 3, 'published', '2026-08-31 04:08:21', 1, 1, 1, '2026-09-10 04:08:21', '2026-09-10 04:08:21', NULL);
INSERT INTO `projects` (`id`, `project_code`, `title`, `slug`, `summary`, `content_html`, `category_id`, `client_name`, `location`, `completion_year`, `scope_of_work`, `cover_image_id`, `cover_alt`, `meta_title`, `meta_description`, `is_featured`, `sort_order`, `status`, `published_at`, `lock_version`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (6, 'PRJ-2023-TTL', 'Teluk Lamong Port Terminal Infrastructure', 'teluk-lamong-port-terminal-infrastructure', 'Harsh-marine environment low-voltage distribution panels designed to IP66 standards with anti-corrosive stainless steel enclosures.', '<p>Harsh-marine environment low-voltage distribution panels designed to IP66 standards with anti-corrosive stainless steel enclosures.</p><p>Equipped with Heavy Duty Marine IP66 Panels • Fluke Power Analyzers to ensure full industrial compliance under SPLN and IEC 61439 standards.</p>', 8, 'PT Terminal Teluk Lamong (Pelindo)', 'Surabaya Port Zone', 2023, 'Heavy Duty Marine IP66 Panels • Fluke Power Analyzers', NULL, 'Teluk Lamong Marine IP66 Distribution Switchgear', 'Teluk Lamong Port Terminal Infrastructure | PT. Anugerah Tama Sejati', 'Harsh-marine environment low-voltage distribution panels designed to IP66 standards with anti-corrosive stainless steel enclosures.', 1, 4, 'published', '2026-07-27 04:08:25', 1, 1, 1, '2026-09-10 04:08:25', '2026-09-10 04:08:25', NULL);
