INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (15, 'company_profile_drive_url', 'https://drive.google.com/file/d/1ats_corporate_profile_2026_demo/view', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (16, 'company_profile_description', 'Dokumen profil resmi mencakup legalitas lengkap, otorisasi distributor resmi global (Schneider Electric, Legrand, GAE, Socomec), rekam jejak suplai proyek industri, dan kesiapan persediaan gudang Surabaya.', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (17, 'company_vision', 'PT. Anugerah Tama Sejati is a creative, innovative, trusted and to be a mainstay for our customer. And to become a healthy and growing company for our employees.', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (18, 'company_mission', 'PT Anugerah Tama Sejati is committed in providing the best service with professionalism in giving solutions to fulfill our customer’s needs.', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (19, 'company_story_p1', 'PT. Anugerah Tama Sejati or shortened as PT ATS was formed in 1st august 2019, located in Surabaya, East Java, Indonesia. Our Company engaged in electrical equipment for industries.', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (20, 'company_story_p2', 'Besides selling electrical equipment for industry, PT Anugerah Tama Sejati provide solutions and give the best service for all of our customers.', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (21, 'company_story_p3', 'Over the years, we have established ourselves as a vital supply chain partner for prominent manufacturing plants, EPC contractors, certified panel builders, and infrastructure developers across Indonesia. As an authorized distributor for leading global brands—including Schneider Electric, Legrand, GAE Group, and Socomec—we deliver genuine low-voltage power distribution switchgear, motor controls, VFD inverters, and digital metering systems backed by full manufacturer warranties and verified Certificates of Origin (COO).', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (22, 'company_story_p4', 'We understand that operational uptime and personnel safety require absolute precision. Beyond component distribution, our certified sales engineers provide dedicated technical consultation, Bill of Quantities (BoQ) optimization, and protection coordination support. Supported by extensive ready-stock warehousing in Surabaya and reliable nationwide freight logistics, PT ATS is committed to preventing project downtime, safeguarding critical assets, and driving sustainable industrial growth for all stakeholders.', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (23, 'stat_experience_years', '7+', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (24, 'stat_clients_count', '1,000+', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (25, 'stat_guarantee_percent', '100%', 'about_us', '2026-09-10 02:57:02', '2026-09-10 02:57:02');
