INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (27, 'panel_project_doc_title', 'ATS Panel Maker & Engineering Project Reference', 'about_us', '2026-09-10 03:05:22', '2026-09-10 03:05:22');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES (28, 'panel_project_doc_version', 'Edisi 2026', 'about_us', '2026-09-10 03:05:22', '2026-09-10 03:05:22');
